   User? _user(HttpRequest request, {String? role}) {
     final user = users[request.headers.value('X-Usuario')];
     if (user == null) return null;
     if (role != null && user.role != role)
       return User('', '__forbidden__', 'forbidden');
     return user;
   }
 
